{
  "title": "URL Shortener Service",
  "summary": "A service that creates short links for http/https URLs, with an optional custom alias and expiry, and redirects short codes to their long URLs. It records clicks and exposes per-link statistics (clicks per day and top referrers). Redirects must keep working when the cache is unavailable and must sustain 1,000 redirects per second on a single node.",
  "goals": [
    "Create a short link for a valid long URL, with an optional custom alias and optional expiry time",
    "Redirect a short code to its long URL, and refuse expired or unknown codes with distinct responses",
    "Record clicks and report clicks per day and top referrers for each link",
    "Reject unsafe URLs: only http and https, no private, loopback or link-local targets",
    "Degrade gracefully: redirects still work from the database when the cache fails",
    "Keep all code and tests under com.agentic.shortener, provable with H2 and MockMvc in the default Maven build"
  ],
  "nonFunctional": [
    "Throughput: sustain 1,000 redirects/s on one node (proven by a k6 script that the build does not run)",
    "Latency (proposed target): redirect p95 < 50 ms and p99 < 150 ms at 1,000 req/s with a warm cache (k6)",
    "Resilience: with the cache down, redirects still succeed from the database, with p95 < 150 ms at 1,000 req/s (k6); functional behaviour is proven by an MockMvc test with a failing cache",
    "Redirect availability must not depend on click recording: a click-recording failure never changes the redirect response",
    "Tests must run with H2 and MockMvc only, with no Docker, network or DNS resolution",
    "The URL safety check must be deterministic and offline (no DNS lookups)"
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "given": "No link exists for a valid URL such as https://example.com/some/long/path?q=1",
      "when": "POST /api/links is called with {\"url\": \"https://example.com/some/long/path?q=1\"}",
      "then": "The response is 201 with a generated code (7 chars, base62), the shortUrl, the original url, and a null expiresAt; the link is persisted"
    },
    {
      "id": "AC2",
      "given": "The alias 'my-link' is not in use",
      "when": "POST /api/links is called with a valid url and alias 'my-link'",
      "then": "The response is 201 and the code is exactly 'my-link'; GET /my-link redirects to the url"
    },
    {
      "id": "AC3",
      "given": "A link with alias 'taken' already exists pointing to URL A",
      "when": "POST /api/links is called with alias 'taken' and a different URL B",
      "then": "The response is 409 and the existing link still redirects to URL A"
    },
    {
      "id": "AC4",
      "given": "Alias rules are 3-32 characters from [A-Za-z0-9_-], and reserved words (api, health, actuator, error) are not allowed",
      "when": "POST /api/links is called with alias 'ab', an alias of 33 characters, 'bad alias!', or 'api'",
      "then": "Each request returns 400 with an error naming the alias field, and no link is created"
    },
    {
      "id": "AC5",
      "given": "The current time is T",
      "when": "POST /api/links is called with expiresAt (ISO-8601 UTC instant) in the future, and again with expiresAt at or before T",
      "then": "The future request returns 201 and echoes expiresAt; the past or present request returns 400 and creates no link"
    },
    {
      "id": "AC6",
      "given": "An active link exists for code C pointing to https://example.com/target",
      "when": "GET /C is called",
      "then": "The response is 302 with Location: https://example.com/target and no response body is required"
    },
    {
      "id": "AC7",
      "given": "No link exists for code 'nope'",
      "when": "GET /nope is called",
      "then": "The response is 404 and no click is recorded"
    },
    {
      "id": "AC8",
      "given": "A link exists whose expiresAt is in the past according to the application clock",
      "when": "GET /{code} is called",
      "then": "The response is 410 Gone, there is no Location header, and no click is recorded"
    },
    {
      "id": "AC9",
      "given": "Only http and https schemes are allowed",
      "when": "POST /api/links is called with ftp://example.com/f, javascript:alert(1), file:///etc/passwd, data:text/html,hi, or a URL with embedded credentials (https://user:pw@example.com)",
      "then": "Each request returns 400 with an error naming the url field and no link is created"
    },
    {
      "id": "AC10",
      "given": "Private, loopback, link-local and unspecified targets are forbidden (checked on literal hosts, without DNS)",
      "when": "POST /api/links is called with http://localhost/, http://127.0.0.1/, http://10.0.0.5/, http://172.16.0.1/, http://192.168.1.1/, http://169.254.169.254/, http://0.0.0.0/, http://[::1]/, or http://[fd00::1]/",
      "then": "Each request returns 400 with an error naming the url field and no link is created"
    },
    {
      "id": "AC11",
      "given": "URL validation also covers structure and length",
      "when": "POST /api/links is called with a missing, blank, or malformed url (no host, e.g. 'http://'), or a url longer than 2048 characters",
      "then": "Each request returns 400 and no link is created; a public https URL of exactly 2048 characters is accepted"
    },
    {
      "id": "AC12",
      "given": "A link has 2 clicks on 2025-01-01 UTC and 3 clicks on 2025-01-02 UTC",
      "when": "GET /api/links/{code}/stats is called",
      "then": "The response is 200 with totalClicks 5 and clicksPerDay containing {date: 2025-01-01, clicks: 2} and {date: 2025-01-02, clicks: 3}, ordered by date ascending, with days that have no clicks omitted"
    },
    {
      "id": "AC13",
      "given": "A link has received clicks with Referer hosts a.com x5, b.com x3, c.com x1",
      "when": "GET /api/links/{code}/stats is called",
      "then": "topReferrers lists a.com (5), b.com (3), c.com (1) in descending click order, with at most 10 entries, ties broken alphabetically"
    },
    {
      "id": "AC14",
      "given": "A link is visited once with no Referer header and once with an unparseable Referer value",
      "when": "GET /api/links/{code}/stats is called",
      "then": "Both clicks are counted in totalClicks and are grouped under the referrer label 'direct'"
    },
    {
      "id": "AC15",
      "given": "One link has no clicks and another code does not exist",
      "when": "GET /api/links/{code}/stats is called for each",
      "then": "The existing link returns 200 with totalClicks 0 and empty clicksPerDay and topReferrers; the unknown code returns 404"
    },
    {
      "id": "AC16",
      "given": "An active link exists and the cache component is configured to throw on every read and write",
      "when": "GET /{code} is called",
      "then": "The response is still 302 with the correct Location, resolved from the database, and the clicks are still recorded"
    },
    {
      "id": "AC17",
      "given": "A link was cached while active and has since passed its expiresAt",
      "when": "GET /{code} is called",
      "then": "The response is 410 Gone; a cache hit never bypasses the expiry check"
    },
    {
      "id": "AC18",
      "given": "Click recording is configured to fail (for example the repository throws)",
      "when": "GET /{code} is called for an active link",
      "then": "The response is still 302 with the correct Location and the failure is logged"
    },
    {
      "id": "AC19",
      "given": "The same long URL is submitted twice without an alias",
      "when": "POST /api/links is called twice",
      "then": "Two distinct codes are returned, each redirecting to the URL, and each has independent statistics"
    }
  ],
  "ambiguities": [
    {
      "question": "Who may create links and read statistics? The requirement mentions no authentication or ownership, and stats expose visitor referrer data.",
      "proposedDefault": "No authentication in this scope: anyone can create links and read stats by code. Authentication and ownership are out of scope, and a follow-up should add them before any public deployment.",
      "confidence": "LOW"
    },
    {
      "question": "What referrer data is stored and for how long? Full Referer URLs may contain personal data or tokens, and no retention period is given for click data.",
      "proposedDefault": "Store only the host of the Referer header (no path or query), or 'direct' when absent or unparseable. Click rows keep a UTC timestamp and the referrer host only (no IP address or user agent) and are retained indefinitely, with no purge job.",
      "confidence": "LOW"
    },
    {
      "question": "How strictly must private and loopback targets be blocked? DNS-based bypasses (a public hostname resolving to a private IP, DNS rebinding) cannot be checked offline.",
      "proposedDefault": "Validate the literal host only: reject localhost, *.localhost, and IP literals in loopback, private (10/8, 172.16/12, 192.168/16, fc00::/7), link-local (169.254/16, fe80::/10) and unspecified ranges, including IPv6 and bracketed forms. Do not resolve DNS at creation or redirect time. Residual risk: hostnames that resolve to private IPs are accepted.",
      "confidence": "LOW"
    },
    {
      "question": "What are the public API paths and payload shapes? The requirement names the capabilities but not the HTTP contract.",
      "proposedDefault": "POST /api/links {url, alias?, expiresAt?} -> 201 {code, shortUrl, url, expiresAt}; GET /{code} -> 302; GET /api/links/{code}/stats -> 200 {code, totalClicks, clicksPerDay:[{date,clicks}], topReferrers:[{referrer,clicks}]}. Errors use a JSON body {error, message, field?}.",
      "confidence": "MEDIUM"
    },
    {
      "question": "Which redirect status code should be used? 301 is cached by browsers, which would hide clicks and make expiry ineffective, while 302/307 are not cached.",
      "proposedDefault": "302 Found, so every click reaches the service and expiry takes effect.",
      "confidence": "MEDIUM"
    },
    {
      "question": "What should an expired link return, and can its alias be reused?",
      "proposedDefault": "Expired links return 410 Gone, unknown codes return 404. Expired codes and aliases are not reusable (the row is retained), so a later create with the same alias returns 409.",
      "confidence": "MEDIUM"
    },
    {
      "question": "What are the custom alias rules?",
      "proposedDefault": "3-32 characters from [A-Za-z0-9_-], case-sensitive, not equal to a reserved word (api, health, actuator, error), and unique across all links including expired ones; conflicts return 409. Generated codes are 7 random base62 characters, regenerated on collision.",
      "confidence": "MEDIUM"
    },
    {
      "question": "What is the latency target? Only throughput (1,000 redirects/s) is given, with no p95 or p99.",
      "proposedDefault": "p95 < 50 ms and p99 < 150 ms at 1,000 req/s with a warm cache on one node; p95 < 150 ms with the cache down. These are verified only by k6 scripts that the build does not run.",
      "confidence": "MEDIUM"
    },
    {
      "question": "How is a 'day' defined for clicks per day, and over what window?",
      "proposedDefault": "Days are UTC calendar days and the stats cover all recorded clicks (no window parameter). Only days with at least one click are listed.",
      "confidence": "MEDIUM"
    },
    {
      "question": "Should the cache be an external system or in-process, and how does the app detect that it is down?",
      "proposedDefault": "Hide the cache behind a port interface. Any exception from the cache is caught, logged, and treated as a miss, falling back to the database. The default implementation is an in-process cache (for example Caffeine) and the tests inject a failing implementation.",
      "confidence": "MEDIUM"
    },
    {
      "question": "Must statistics be immediately consistent with redirects?",
      "proposedDefault": "Each click is written in the redirect request after the target is resolved, and a write failure is swallowed and logged. Under normal operation stats reflect a click as soon as the redirect returns.",
      "confidence": "MEDIUM"
    },
    {
      "question": "How many top referrers are returned?",
      "proposedDefault": "Top 10, ordered by clicks descending and then referrer ascending.",
      "confidence": "HIGH"
    },
    {
      "question": "What are the expiry input format and constraints?",
      "proposedDefault": "expiresAt is an ISO-8601 instant in UTC that must be strictly in the future at creation. It is optional, and null means the link never expires. There is no maximum horizon.",
      "confidence": "HIGH"
    },
    {
      "question": "Does submitting the same long URL twice return the existing link?",
      "proposedDefault": "No. Each create call produces a new link with its own code and statistics.",
      "confidence": "HIGH"
    }
  ],
  "assumptions": [
    "Spring Boot with Spring MVC and JPA; H2 is used in tests, and the production database is configurable and out of scope for the tests",
    "The application uses an injectable Clock so that expiry and day grouping are testable",
    "Maximum URL length is 2048 characters",
    "Redirects are served on GET /{code} at the root path; /api/** is reserved for management endpoints",
    "k6 scripts for the load and cache-down scenarios are delivered under the project (for example src/test/k6) but are not executed by the Maven build",
    "The shortUrl base is configurable (default derived from the request) and is not validated by tests beyond ending with the code",
    "Single-node deployment; no distributed coordination is needed for code uniqueness beyond a database unique constraint"
  ],
  "outOfScope": [
    "Authentication, authorization, user accounts and link ownership",
    "Editing, disabling or deleting links",
    "Rate limiting or abuse and spam detection beyond the URL safety rules",
    "DNS resolution or reachability checks of target URLs, and malware or phishing reputation lookups",
    "Click attributes other than timestamp and referrer host (IP, geo, user agent, device)",
    "QR codes, link previews, bulk import, and analytics dashboards or UI",
    "Distributed or external cache (such as Redis) provisioning, and multi-node deployment",
    "Data retention or purge jobs for expired links and old clicks",
    "Running load tests in the Maven build"
  ]
