{
  "title": "URL shortener service",
  "summary": "A Spring Boot service creates short links (optional custom alias and expiry), redirects short codes to their long URLs, and reports per-link click statistics to the holder of a per-link management token. Creation is guarded by SSRF checks and rate limiting, and redirects are served from a Redis cache that is optional (any cache error falls back to the database). Statistics are recorded asynchronously and privacy-minimally, so a redirect never waits on or fails because of them.",
  "goals": [
    "Create a short link for a long http/https URL, with an optional custom alias and an optional expiry time.",
    "Return an unguessable management token at creation; store only its hash; require it to read statistics.",
    "Redirect a short code to its long URL; creation and redirects are open, with rate limiting on creation only.",
    "Reject unsafe URLs at creation: non-http(s) schemes and any hostname that resolves to a loopback, private, link-local, CGNAT, unique-local or unspecified address, in every encoding including IPv4-mapped IPv6.",
    "Resolve hostnames through an injectable HostResolver at creation only, never at redirect time.",
    "Show per-link clicks per UTC day and top referrer hosts.",
    "Keep only the UTC day and referrer host per click (no IP, no user agent); a scheduled job deletes click data 90 days after the link expires.",
    "Use Redis behind a LinkCache port with short timeouts; any cache error is treated as a miss and served from the database.",
    "Record clicks through a bounded in-memory queue that is batch-flushed and drops on overflow or error, so statistics never block or fail a redirect."
  ],
  "nonFunctional": [
    "Throughput: one node sustains 1,000 redirects/s for 5 minutes with an error rate below 0.1% (proven by a k6 script that the build does not run).",
    "Latency with a healthy cache: p95 redirect latency below 10 ms and p99 below 30 ms at 1,000 redirects/s (k6).",
    "Latency with the cache down: p95 redirect latency below 50 ms at 1,000 redirects/s, with the Redis connect and command timeouts configured at 50 ms or less (k6 for latency; a test asserts the timeout configuration values).",
    "The redirect path performs no synchronous database write and no wait on the click queue; enqueueing is non-blocking.",
    "Click queue: bounded, default capacity 10,000 events; flushed in batches of up to 500 events or every 1 second, whichever comes first; the capacity, batch size and interval are configurable.",
    "The drop count of click events (overflow or flush error) is exposed as a metric or counter.",
    "The management token has at least 128 bits of entropy from a SecureRandom; only a SHA-256 hash is stored; the raw token appears only in the creation response and is never logged.",
    "Hostname resolution at creation has a configurable timeout, default 2 s; a timeout is treated as a rejection.",
    "Creation rate limit is configurable; the default is 30 creations per minute per client address; excess requests get 429 with a Retry-After header.",
    "All acceptance criteria except throughput and latency run in the default Maven build with H2, MockMvc, an injected HostResolver stub, an injected Clock and an injected LinkCache, with no Docker and no network."
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "given": "A HostResolver stub resolves example.test to a public address",
      "when": "POST /api/links is called with {\"url\":\"https://example.test/a/long/path?q=1\"}",
      "then": "The response is 201 with a body containing shortCode (7 characters, base62), shortUrl, the original url and managementToken; the token is at least 22 URL-safe characters."
    },
    {
      "id": "AC2",
      "given": "The alias \"my-link\" is not yet used",
      "when": "A link is created with alias \"my-link\"",
      "then": "The response is 201 and shortCode equals \"my-link\" and GET /my-link redirects to the long URL."
    },
    {
      "id": "AC3",
      "given": "A link with alias \"taken\" already exists",
      "when": "Another creation request uses alias \"taken\"",
      "then": "The response is 409 and the existing link is unchanged."
    },
    {
      "id": "AC4",
      "given": "Alias rules: 3 to 32 characters from [A-Za-z0-9_-], not a reserved word (api, admin, health, actuator)",
      "when": "A creation request uses an alias that is too short, too long, contains other characters, or is reserved",
      "then": "Each request gets 400 with a field error naming alias, and nothing is stored."
    },
    {
      "id": "AC5",
      "given": "The current time is fixed by an injected Clock",
      "when": "A link is created with expiresAt in the past or equal to now",
      "then": "The response is 400 and nothing is stored."
    },
    {
      "id": "AC6",
      "given": "A link exists with expiresAt in the future",
      "when": "The Clock is advanced past expiresAt and GET /{code} is called",
      "then": "The response is 410 with no Location header, and no click is recorded."
    },
    {
      "id": "AC7",
      "given": "An active link exists",
      "when": "GET /{code} is called without following redirects",
      "then": "The response is 302 with Location equal to the stored long URL and Cache-Control: no-store."
    },
    {
      "id": "AC8",
      "given": "No link has the code \"nope123\"",
      "when": "GET /nope123 is called",
      "then": "The response is 404."
    },
    {
      "id": "AC9",
      "given": "A long URL uses a scheme other than http or https (ftp, file, javascript, data), has no host, embeds userinfo (user:pass@), or is longer than 2048 characters",
      "when": "A creation request is submitted",
      "then": "Each request gets 400 with a reason code, and the HostResolver is not called for the scheme, missing-host and length failures."
    },
    {
      "id": "AC10",
      "given": "A HostResolver stub returns, for separate hostnames, one of: 127.0.0.1, 10.0.0.1, 172.16.0.1, 192.168.1.1, 169.254.169.254, 100.64.0.1, 0.0.0.0, ::1, fc00::1, fd12::1, fe80::1, ::, and ::ffff:127.0.0.1 or ::ffff:10.0.0.1 (IPv4-mapped IPv6)",
      "when": "A link creation is requested for each hostname",
      "then": "Every request gets 400 with reason code unsafe_url and nothing is stored."
    },
    {
      "id": "AC11",
      "given": "A HostResolver stub returns multiple addresses for a hostname, one public and one private (or one IPv4-mapped loopback)",
      "when": "A link creation is requested",
      "then": "The request gets 400, because any unsafe resolved address rejects the URL."
    },
    {
      "id": "AC12",
      "given": "The URL host is an IP literal in an alternate encoding: decimal integer (http://2130706433/), hex (http://0x7f000001/), octal (http://0177.0.0.1/), short form (http://127.1/), bracketed IPv6 (http://[::1]/) or bracketed IPv4-mapped IPv6 (http://[::ffff:7f00:1]/)",
      "when": "A link creation is requested",
      "then": "Each request gets 400 after normalising the literal to its binary address; and an IP literal with a public address (such as http://93.184.216.34/) is accepted."
    },
    {
      "id": "AC13",
      "given": "The HostResolver stub fails with an unknown host, or exceeds the resolution timeout",
      "when": "A link creation is requested",
      "then": "The request gets 400 with reason code unresolvable_host and nothing is stored."
    },
    {
      "id": "AC14",
      "given": "A link was created with a HostResolver spy and the spy's invocation count was reset",
      "when": "GET /{code} is called several times, including after the stub is changed to return a private address",
      "then": "Every response is still 302 and the HostResolver spy has zero invocations (no re-resolution at redirect time)."
    },
    {
      "id": "AC15",
      "given": "A link was created and its managementToken was returned",
      "when": "The link row is read directly from H2",
      "then": "The stored token column contains the SHA-256 hash of the token (not the raw token), and no stored column or log capture contains the raw token."
    },
    {
      "id": "AC16",
      "given": "A link with recorded clicks exists",
      "when": "GET /api/links/{code}/stats is called with the correct management token in the Authorization: Bearer header",
      "then": "The response is 200 with the statistics; when the header is missing the response is 401; when the token is wrong, or belongs to a different link, the response is 403 and the body reveals no statistics."
    },
    {
      "id": "AC17",
      "given": "The statistics endpoint is called for a code that does not exist",
      "when": "The request carries any token",
      "then": "The response is 404 (or the same 403 as for a wrong token, whichever is chosen, but identical for every unknown code and every wrong token, so existence cannot be probed through the token check); the chosen behaviour is documented."
    },
    {
      "id": "AC18",
      "given": "The creation rate limit is set to 3 per window in the test configuration, and the Clock is controllable",
      "when": "A fourth creation request comes from the same client address within the window",
      "then": "The response is 429 with a Retry-After header and nothing is stored; a request after the window passes; and any number of GET /{code} redirects from that address is never rate limited."
    },
    {
      "id": "AC19",
      "given": "Clicks were recorded and flushed on several UTC days (Clock-controlled), including one just before and one just after UTC midnight, from several referrer URLs, with one request that had no Referer",
      "when": "The statistics are requested",
      "then": "clicksPerDay lists UTC dates with counts (days without clicks inside the default 30-day window are listed with 0), and topReferrers lists up to 10 referrer hosts by count descending, ties broken alphabetically, with no-referrer clicks counted as \"(direct)\"."
    },
    {
      "id": "AC20",
      "given": "A redirect request carries Referer: https://News.Example.com:8443/path?token=secret, X-Forwarded-For: 203.0.113.9 and a User-Agent header",
      "when": "The click is flushed and the click table is read directly",
      "then": "The stored row contains only the link id, the UTC day and the referrer host \"news.example.com\" (lower case, no port, path or query); the click table has no IP or user-agent column, and none of those values appear in any stored column."
    },
    {
      "id": "AC21",
      "given": "Links exist: A expired 91 days ago, B expired 89 days ago, C has no expiry; each has click rows",
      "when": "The scheduled retention job is run with the Clock fixed",
      "then": "A's click rows are deleted, and B's and C's click rows remain; the job is idempotent (a second run deletes nothing) and a failure of one run does not stop the next scheduled run."
    },
    {
      "id": "AC22",
      "given": "An injected LinkCache is empty and an active link exists in the database",
      "when": "GET /{code} is called twice",
      "then": "Both responses are 302; the first reads the database and populates the cache; the second is served from the cache without a database read of the link."
    },
    {
      "id": "AC23",
