"},{"path":"src/main/java/com/agentic/shortener/config/ShortenerProperties.java","action":"create","content":"package com.agentic.shortener.config;

import java.time.Duration;
import java.util.List;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;

/** Typed settings under the shortener prefix; defaults apply when a property is absent. */
@ConfigurationProperties(prefix = "shortener")
public record ShortenerProperties(
        @DefaultValue("http://localhost:8080") String baseUrl,
        @DefaultValue Links links,
        @DefaultValue Clicks clicks,
        @DefaultValue RateLimit rateLimit,
        @DefaultValue Stats stats,
        @DefaultValue Retention retention,
        @DefaultValue Resolver resolver,
        @DefaultValue Cache cache) {

    /** Code generation, alias and expiry rules. */
    public record Links(
            @DefaultValue("7") int codeLength,
            @DefaultValue("5") int maxCodeAttempts,
            @DefaultValue("365d") Duration maxExpiry,
            @DefaultValue({"api", "actuator", "health", "error", "static"}) List<String> reservedAliases) {
    }

    /** Bounded click queue and batch flush settings. */
    public record Clicks(
            @DefaultValue("10000") int queueCapacity,
            @DefaultValue("1s") Duration flushInterval,
            @DefaultValue("500") int batchSize) {
    }

    /** Per-client creation rate limit. */
    public record RateLimit(
            @DefaultValue("20") int creationsPerWindow,
            @DefaultValue("1m") Duration window,
            @DefaultValue("false") boolean trustForwardedFor) {
    }

    /** Statistics query defaults and bounds. */
    public record Stats(
            @DefaultValue("30") int defaultDays,
            @DefaultValue("90") int maxDays,
            @DefaultValue("10") int topReferrers) {
    }

    /** Click data retention after link expiry. */
    public record Retention(
            @DefaultValue("90d") Duration afterExpiry,
            @DefaultValue("0 15 3 * * *") String cron) {
    }

    /** DNS resolution settings. */
    public record Resolver(@DefaultValue("2s") Duration timeout) {
    }

    /** Redirect cache settings. */
    public record Cache(@DefaultValue("1h") Duration ttl) {
    }
}
"},{"path":"src/main/java/com/agentic/shortener/config/AppConfig.java","action":"create","content":"package com.agentic.shortener.config;

import java.time.Clock;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;

/** Shared application configuration: UTC Clock, scheduling and typed properties. */
@Configuration
@EnableScheduling
@EnableConfigurationProperties(ShortenerProperties.class)
public class AppConfig {

    /** System UTC clock; tests override it with a @Primary Clock bean. */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/ErrorCode.java","action":"create","content":"package com.agentic.shortener.common;

import org.springframework.http.HttpStatus;

/** Stable error codes returned in ErrorBody, each with its HTTP status. */
public enum ErrorCode {
    INVALID_URL(HttpStatus.BAD_REQUEST),
    UNSAFE_URL(HttpStatus.BAD_REQUEST),
    INVALID_ALIAS(HttpStatus.BAD_REQUEST),
    ALIAS_TAKEN(HttpStatus.CONFLICT),
    INVALID_EXPIRY(HttpStatus.BAD_REQUEST),
    INVALID_REQUEST(HttpStatus.BAD_REQUEST),
    UNAUTHORIZED(HttpStatus.UNAUTHORIZED),
    NOT_FOUND(HttpStatus.NOT_FOUND),
    GONE(HttpStatus.GONE),
    RATE_LIMITED(HttpStatus.TOO_MANY_REQUESTS),
    INTERNAL_ERROR(HttpStatus.INTERNAL_SERVER_ERROR);

    private final HttpStatus status;

    ErrorCode(HttpStatus status) {
        this.status = status;
    }

    /** HTTP status sent with this code. */
    public HttpStatus status() {
        return status;
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/ErrorBody.java","action":"create","content":"package com.agentic.shortener.common;

/** JSON error response: a stable ErrorCode name and a human-readable message. */
public record ErrorBody(String code, String message) {
}
"},{"path":"src/main/java/com/agentic/shortener/common/ApiException.java","action":"create","content":"package com.agentic.shortener.common;

/** Business failure that maps to an ErrorCode and its HTTP status. */
public class ApiException extends RuntimeException {

    private final ErrorCode code;

    public ApiException(ErrorCode code, String message) {
        super(message);
        this.code = code;
    }

    /** Error code for the response body and status. */
    public ErrorCode code() {
        return code;
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/RateLimitExceededException.java","action":"create","content":"package com.agentic.shortener.common;

/** Creation rate limit exceeded; the response carries a Retry-After header. */
public class RateLimitExceededException extends ApiException {

    private final long retryAfterSeconds;

    public RateLimitExceededException(long retryAfterSeconds) {
        super(ErrorCode.RATE_LIMITED, "Too many link creations, retry later");
        this.retryAfterSeconds = Math.max(1, retryAfterSeconds);
    }

    /** Whole seconds until the client may retry, at least 1. */
    public long retryAfterSeconds() {
        return retryAfterSeconds;
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/GlobalExceptionHandler.java","action":"create","content":"package com.agentic.shortener.common;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.TypeMismatchException;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.FieldError;
import org.springframework.web.ErrorResponse;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/** Maps every exception to an ErrorBody with a stable error code; never leaks internals. */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
        ResponseEntity.BodyBuilder builder = ResponseEntity.status(ex.code().status());
        if (ex instanceof RateLimitExceededException limited) {
            builder.header(HttpHeaders.RETRY_AFTER, Long.toString(limited.retryAfterSeconds()));
        }
        return builder.body(new ErrorBody(ex.code().name(), ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorBody> handleInvalidBody(MethodArgumentNotValidException ex) {
        FieldError error = ex.getBindingResult().getFieldError();
        if (error == null) {
            return of(ErrorCode.INVALID_REQUEST, "Invalid request");
        }
        ErrorCode code = switch (error.getField()) {
            case "url" -> ErrorCode.INVALID_URL;
            case "alias" -> ErrorCode.INVALID_ALIAS;
            case "expiresAt" -> ErrorCode.INVALID_EXPIRY;
            default -> ErrorCode.INVALID_REQUEST;
        };
        return of(code, error.getField() + ": " + error.getDefaultMessage());
    }

    @ExceptionHandler({HttpMessageNotReadableException.class, TypeMismatchException.class})
    public ResponseEntity<ErrorBody> handleMalformed(Exception ex) {
        return of(ErrorCode.INVALID_REQUEST, "Malformed request");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorBody> handleOther(Exception ex) {
        if (ex instanceof ErrorResponse response && !response.getStatusCode().is5xxServerError()) {
            HttpStatusCode status = response.getStatusCode();
            ErrorCode code = status.value() == HttpStatus.NOT_FOUND.value()
                    ? ErrorCode.NOT_FOUND : ErrorCode.INVALID_REQUEST;
            return ResponseEntity.status(status).body(new ErrorBody(code.name(), "Request could not be processed"));
        }
        log.error("Unhandled exception", ex);
        return of(ErrorCode.INTERNAL_ERROR, "Internal error");
    }

    private static ResponseEntity<ErrorBody> of(ErrorCode code, String message) {
        return ResponseEntity.status(code.status()).body(new ErrorBody(code.name(), message));
    }
}
