"},{"path":"src/main/java/com/agentic/shortener/domain/Link.java","action":"create","content":"package com.agentic.shortener.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;

/** A short link; only the SHA-256 hash of its management token is stored. */
@Entity
@Table(name = "links")
public class Link {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "code", nullable = false, unique = true, length = 32)
    private String code;

    @Column(name = "long_url", nullable = false, length = 2048)
    private String longUrl;

    @Column(name = "token_hash", nullable = false, length = 64)
    private String tokenHash;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    @Column(name = "expires_at")
    private Instant expiresAt;

    protected Link() {
    }

    public Link(String code, String longUrl, String tokenHash, Instant createdAt, Instant expiresAt) {
        this.code = code;
        this.longUrl = longUrl;
        this.tokenHash = tokenHash;
        this.createdAt = createdAt;
        this.expiresAt = expiresAt;
    }

    public Long getId() {
        return id;
    }

    public String getCode() {
        return code;
    }

    public String getLongUrl() {
        return longUrl;
    }

    public String getTokenHash() {
        return tokenHash;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getExpiresAt() {
        return expiresAt;
    }

    /** True when expiresAt is set and is less than or equal to now. */
    public boolean isExpiredAt(Instant now) {
        return expiresAt != null && !expiresAt.isAfter(now);
    }
}
"},{"path":"src/main/java/com/agentic/shortener/domain/Click.java","action":"create","content":"package com.agentic.shortener.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** Click aggregate per link, UTC day and referrer host; holds no IP, user agent, path or timestamp. */
@Entity
@Table(name = "click_counts")
public class Click {

    /** Referrer host stored for clicks without a usable Referer header. */
    public static final String DIRECT = "(direct)";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "link_id", nullable = false)
    private Long linkId;

    @Column(name = "click_day", nullable = false)
    private LocalDate day;

    @Column(name = "referrer_host", nullable = false, length = 255)
    private String referrerHost;

    @Column(name = "click_count", nullable = false)
    private long count;

    protected Click() {
    }

    public Click(Long linkId, LocalDate day, String referrerHost, long count) {
        this.linkId = linkId;
        this.day = day;
        this.referrerHost = referrerHost;
        this.count = count;
    }

    public Long getId() {
        return id;
    }

    public Long getLinkId() {
        return linkId;
    }

    public LocalDate getDay() {
        return day;
    }

    public String getReferrerHost() {
        return referrerHost;
    }

    public long getCount() {
        return count;
    }

    /** Adds delta clicks to this aggregate. */
    public void increment(long delta) {
        this.count += delta;
    }
}
