import java.time.Instant;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.transaction.annotation.Transactional;

/** Persistence and aggregate queries for Click. */
public interface ClickRepository extends JpaRepository<Click, Long> {

    Optional<Click> findByLinkIdAndDayAndReferrerHost(Long linkId, LocalDate day, String referrerHost);

    List<Click> findByLinkId(Long linkId);

    /** Daily totals from the given day onwards, in ascending date order. */
    @Query("select c.day as day, sum(c.count) as total from Click c"
            + " where c.linkId = :linkId and c.day >= :from group by c.day order by c.day")
    List<DailyClickTotal> dailyTotals(@Param("linkId") Long linkId, @Param("from") LocalDate from);

    /** Referrer totals from the given day onwards, by count descending then host; the page bounds the size. */
    @Query("select c.referrerHost as host, sum(c.count) as total from Click c"
            + " where c.linkId = :linkId and c.day >= :from group by c.referrerHost"
            + " order by sum(c.count) desc, c.referrerHost")
    List<ReferrerClickTotal> topReferrers(@Param("linkId") Long linkId, @Param("from") LocalDate from, Pageable page);

    /** Deletes clicks of links whose expiresAt is less than or equal to the cutoff. */
    @Transactional
    @Modifying
    @Query("delete from Click c where c.linkId in"
            + " (select l.id from Link l where l.expiresAt is not null and l.expiresAt <= :cutoff)")
    int deleteForLinksExpiredAtOrBefore(@Param("cutoff") Instant cutoff);
}
