import java.time.Clock;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;

/** Shared application configuration: UTC clock, scheduling and typed properties. */
@Configuration
@EnableScheduling
@EnableConfigurationProperties(ShortenerProperties.class)
public class AppConfig {

    /** System UTC clock; tests override it with a @Primary Clock bean. */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}
"},{"path":"src/main/java/com/agentic/shortener/config/ShortenerProperties.java","action":"create","content":"package com.agentic.shortener.config;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import java.time.Duration;
import java.util.List;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;
import org.springframework.validation.annotation.Validated;

/** Typed settings under prefix 'shortener'; every value has an in-code default. */
@Validated
@ConfigurationProperties(prefix = "shortener")
public record ShortenerProperties(
        @DefaultValue("http://localhost:8080") @NotBlank String baseUrl,
        @DefaultValue @Valid Links links,
        @DefaultValue @Valid Cache cache,
        @DefaultValue @Valid Resolver resolver,
        @DefaultValue @Valid Clicks clicks,
        @DefaultValue @Valid RateLimit rateLimit,
        @DefaultValue @Valid Stats stats,
        @DefaultValue @Valid Retention retention) {

    /** Code generation and alias/expiry rules. */
    public record Links(
            @DefaultValue("7") @Positive int codeLength,
            @DefaultValue("365d") Duration maxExpiry,
            @DefaultValue({"api", "actuator", "health", "error", "static"}) List<String> reservedAliases) {
    }

    /** Redis link cache entry TTL and key prefix. */
    public record Cache(@DefaultValue("1h") Duration ttl, @DefaultValue("link:") @NotBlank String keyPrefix) {
    }

    /** Default HostResolver timeout. */
    public record Resolver(@DefaultValue("2s") Duration timeout) {
    }

    /** Bounded click queue and batch flush settings. */
    public record Clicks(
            @DefaultValue("10000") @Positive int queueCapacity,
            @DefaultValue("1s") Duration flushInterval,
            @DefaultValue("500") @Positive int batchSize) {
    }

    /** Fixed-window creation rate limit per client. */
    public record RateLimit(
            @DefaultValue("20") @Positive int requestsPerWindow,
            @DefaultValue("1m") Duration window,
            @DefaultValue("false") boolean trustedProxy) {
    }

    /** Statistics window and referrer list size. */
    public record Stats(
            @DefaultValue("30") @Positive int defaultDays,
            @DefaultValue("90") @Positive int maxDays,
            @DefaultValue("10") @Positive int topReferrers) {
    }

    /** Click retention after link expiry and the job's cron. */
    public record Retention(
            @DefaultValue("90d") Duration afterExpiry,
            @DefaultValue("0 30 3 * * *") @NotBlank String cron) {
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/ErrorCode.java","action":"create","content":"package com.agentic.shortener.common;

import org.springframework.http.HttpStatus;

/** Machine-readable error codes with their HTTP status. */
public enum ErrorCode {
    INVALID_REQUEST(HttpStatus.BAD_REQUEST),
    INVALID_URL(HttpStatus.BAD_REQUEST),
    UNSAFE_URL(HttpStatus.BAD_REQUEST),
    INVALID_ALIAS(HttpStatus.BAD_REQUEST),
    ALIAS_TAKEN(HttpStatus.CONFLICT),
    INVALID_EXPIRY(HttpStatus.BAD_REQUEST),
    UNAUTHORIZED(HttpStatus.UNAUTHORIZED),
    NOT_FOUND(HttpStatus.NOT_FOUND),
    GONE(HttpStatus.GONE),
    RATE_LIMITED(HttpStatus.TOO_MANY_REQUESTS),
    INTERNAL_ERROR(HttpStatus.INTERNAL_SERVER_ERROR);

    private final HttpStatus status;

    ErrorCode(HttpStatus status) {
        this.status = status;
    }

    /** HTTP status returned for this code. */
    public HttpStatus status() {
        return status;
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/ErrorBody.java","action":"create","content":"package com.agentic.shortener.common;

/** JSON error response body. */
public record ErrorBody(String code, String message) {

    /** Builds a body from an error code and message. */
    public static ErrorBody of(ErrorCode code, String message) {
        return new ErrorBody(code.name(), message);
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/ApiException.java","action":"create","content":"package com.agentic.shortener.common;

/** Business failure mapped by GlobalExceptionHandler to its ErrorCode status. */
public class ApiException extends RuntimeException {

    private final ErrorCode errorCode;

    public ApiException(ErrorCode errorCode, String message) {
        super(message);
        this.errorCode = errorCode;
    }

    public ErrorCode getErrorCode() {
        return errorCode;
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/RateLimitedException.java","action":"create","content":"package com.agentic.shortener.common;

/** Creation rate limit exceeded; carries the Retry-After value in seconds. */
public class RateLimitedException extends ApiException {

    private final long retryAfterSeconds;

    public RateLimitedException(long retryAfterSeconds) {
        super(ErrorCode.RATE_LIMITED, "Too many link creations, retry later");
        this.retryAfterSeconds = Math.max(1, retryAfterSeconds);
    }

    public long getRetryAfterSeconds() {
        return retryAfterSeconds;
    }
}
"},{"path":"src/main/java/com/agentic/shortener/common/GlobalExceptionHandler.java","action":"create","content":"package com.agentic.shortener.common;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingServletRequestParameterException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.servlet.resource.NoResourceFoundException;

/** Maps exceptions to ErrorBody responses; never adds a Location header. */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(RateLimitedException.class)
    public ResponseEntity<ErrorBody> handleRateLimited(RateLimitedException ex) {
        return ResponseEntity.status(ex.getErrorCode().status())
                .header(HttpHeaders.RETRY_AFTER, Long.toString(ex.getRetryAfterSeconds()))
                .body(ErrorBody.of(ex.getErrorCode(), ex.getMessage()));
    }

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.getErrorCode().status()).body(ErrorBody.of(ex.getErrorCode(), ex.getMessage()));
    }

    @ExceptionHandler({HttpMessageNotReadableException.class, MethodArgumentNotValidException.class,
            MethodArgumentTypeMismatchException.class, MissingServletRequestParameterException.class})
    public ResponseEntity<ErrorBody> handleBadRequest(Exception ex) {
        return build(ErrorCode.INVALID_REQUEST, "Malformed request");
    }

    @ExceptionHandler(NoResourceFoundException.class)
    public ResponseEntity<ErrorBody> handleNoResource(NoResourceFoundException ex) {
        return build(ErrorCode.NOT_FOUND, "Not found");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorBody> handleUnexpected(Exception ex) {
        log.error("Unhandled exception", ex);
        return build(ErrorCode.INTERNAL_ERROR, "Internal error");
    }

    private static ResponseEntity<ErrorBody> build(ErrorCode code, String message) {
        return ResponseEntity.status(code.status()).body(ErrorBody.of(code, message));
    }
}
