"},{"path":"src/main/java/com/agentic/shortener/domain/ClickRepository.java","action":"create","content":"package com.agentic.shortener.domain;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

/** Click aggregate persistence and statistics queries. */
public interface ClickRepository extends JpaRepository<Click, Long> {

    /** Adds delta to an existing aggregate row; returns rows updated (0 means insert a new Click). */
    @Modifying
    @Query("update Click c set c.count = c.count + :delta "
            + "where c.linkId = :linkId and c.day = :day and c.referrerHost = :host")
    int increment(@Param("linkId") long linkId, @Param("day") LocalDate day,
                  @Param("host") String host, @Param("delta") long delta);

    /** Clicks per day from 'from' inclusive, ascending by day. */
    @Query("select new com.agentic.shortener.domain.DayCount(c.day, sum(c.count)) from Click c "
            + "where c.linkId = :linkId and c.day >= :from group by c.day order by c.day")
    List<DayCount> dailyCounts(@Param("linkId") long linkId, @Param("from") LocalDate from);

    /** Referrer hosts from 'from' inclusive, by count descending then host; page size limits results. */
    @Query("select new com.agentic.shortener.domain.ReferrerCount(c.referrerHost, sum(c.count)) from Click c "
            + "where c.linkId = :linkId and c.day >= :from group by c.referrerHost "
            + "order by sum(c.count) desc, c.referrerHost")
    List<ReferrerCount> topReferrers(@Param("linkId") long linkId, @Param("from") LocalDate from, Pageable page);

    /** Deletes clicks of links whose expiresAt is before cutoff; idempotent. */
    @Modifying
    @Query("delete from Click c where c.linkId in "
            + "(select l.id from Link l where l.expiresAt is not null and l.expiresAt < :cutoff)")
    int deleteForLinksExpiredBefore(@Param("cutoff") Instant cutoff);
}
